import{_ as a,o as s,c as n,a2 as t}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"17 - Connection Pooling","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/17-connection-pooling.md","filePath":"developers/design-documentation/17-connection-pooling.md"}'),i={name:"developers/design-documentation/17-connection-pooling.md"};function o(r,e,l,c,p,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="_17-connection-pooling" tabindex="-1">17 - Connection Pooling <a class="header-anchor" href="#_17-connection-pooling" aria-label="Permalink to &quot;17 - Connection Pooling&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Tradeboard pools broker WebSocket adapters per broker and user. A <code>ConnectionPool</code> allocates subscriptions across adapter connections while a process-local <code>SharedZmqPublisher</code> sends every adapter&#39;s normalized ticks to the market-data proxy.</p><p>The default pool limits are 1,000 symbols per broker connection and three connections. These are capacity limits, not guarantees; broker-specific limits and capabilities still apply.</p><h2 id="topology" tabindex="-1">Topology <a class="header-anchor" href="#topology" aria-label="Permalink to &quot;Topology&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>broker/user ConnectionPool</span></span>
<span class="line"><span>  |-- adapter 1 (up to configured symbol limit)</span></span>
<span class="line"><span>  |-- adapter 2</span></span>
<span class="line"><span>  \`-- adapter 3</span></span>
<span class="line"><span>          |</span></span>
<span class="line"><span>          v</span></span>
<span class="line"><span>SharedZmqPublisher (PUB connects)</span></span>
<span class="line"><span>          |</span></span>
<span class="line"><span>          v</span></span>
<span class="line"><span>tcp://ZMQ_HOST:ZMQ_PORT</span></span>
<span class="line"><span>          ^</span></span>
<span class="line"><span>          |</span></span>
<span class="line"><span>WebSocketProxy (SUB binds)</span></span>
<span class="line"><span>          |</span></span>
<span class="line"><span>          v</span></span>
<span class="line"><span>authenticated WebSocket clients</span></span></code></pre></div><p>The proxy&#39;s SUB socket is the sole binder on the configured endpoint. Broker market-data publishers and cache-invalidation publishers connect to that fixed endpoint. There is no publisher bind or fallback-port scan; this avoids cross-process bind races that can acknowledge subscriptions without delivering ticks.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MAX_SYMBOLS_PER_WEBSOCKET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MAX_WEBSOCKET_CONNECTIONS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ENABLE_CONNECTION_POOLING</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ZMQ_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ZMQ_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">5555</span></span></code></pre></div><p>These are the defaults read in <code>websocket_proxy/base_adapter.py</code> and <code>websocket_proxy/connection_manager.py</code>. Setting <code>ENABLE_CONNECTION_POOLING=false</code> falls back to one connection per broker.</p><p><code>ZMQ_HOST</code> defaults to loopback. Multi-host deployments can point publishers at the host where the proxy binds, but the endpoint must be consistent for all processes.</p><h2 id="pool-allocation" tabindex="-1">Pool Allocation <a class="header-anchor" href="#pool-allocation" aria-label="Permalink to &quot;Pool Allocation&quot;">​</a></h2><p><code>ConnectionPool</code> tracks <code>(symbol, exchange, mode)</code> subscriptions and the adapter that owns each one.</p><ol><li>Reuse an existing adapter with capacity.</li><li>Create and initialize another adapter when all current adapters are full.</li><li>Reject the subscription when the configured connection and symbol capacity is exhausted.</li><li>Unsubscribe from the broker only when the last local client releases the subscription.</li></ol><p>Requested depth levels are retained with the subscription so authentication recovery can restore depth subscriptions correctly. Authentication-like broker failures trigger a token refresh and subscription restoration path.</p><h2 id="shared-publisher" tabindex="-1">Shared Publisher <a class="header-anchor" href="#shared-publisher" aria-label="Permalink to &quot;Shared Publisher&quot;">​</a></h2><p>The pool creates one thread-safe <code>SharedZmqPublisher</code> singleton per process. Pooled adapters publish through that object instead of creating individual ZeroMQ contexts and sockets. The publisher connects lazily and idempotently to <code>tcp://&lt;ZMQ_HOST&gt;:&lt;ZMQ_PORT&gt;</code>.</p><p>The WebSocket proxy maintains an O(1) subscription index keyed by symbol, exchange, and numeric mode. A higher-mode tick can satisfy lower-mode subscribers. Topics ending in <code>_positions</code> and <code>_margins</code> are private account events and are skipped entirely. Topics ending in <code>_orders</code> are the order-update relay published by <code>subscribers/wsproxy_subscriber.py</code>; the proxy routes them only to the owning authenticated client that sent <code>subscribe_orders</code>, never to the market-data fan-out.</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><ul><li>Adapter connections are created on demand and closed during pool cleanup.</li><li>The shared publisher is closed only after the pools using it are released.</li><li>Re-authentication evicts a disconnected or broker-mismatched cached adapter before rebuilding it with current credentials.</li><li>Proxy shutdown closes client sockets, adapters, the ZMQ socket, and its asyncio tasks.</li></ul><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>websocket_proxy/connection_manager.py</code></td><td>Pool allocation, recovery, shared publisher</td></tr><tr><td><code>websocket_proxy/base_adapter.py</code></td><td>Base broker adapter and non-pooled publisher connection</td></tr><tr><td><code>websocket_proxy/broker_factory.py</code></td><td>Broker adapter and pool construction</td></tr><tr><td><code>websocket_proxy/server.py</code></td><td>SUB binder, client subscriptions, tick fan-out</td></tr></tbody></table>`,22)])])}const u=a(i,[["render",o]]);export{b as __pageData,u as default};
